      grid-template-columns: repeat(5, minmax(0, 1fr));
      gap: 8px;
      margin-bottom: 10px;
    }

    .stat {
      background: #fff;
      border: 1px solid rgba(0,0,0,.1);
      border-radius: 12px;
      padding: 8px 10px;
      font-size: 14px;
      text-align: center;
    }

