    }

    .btn {
      border: 1px solid rgba(0,0,0,.18);
      border-radius: 10px;
      background: #fff;
      padding: 8px 12px;
      cursor: pointer;
    }

    .actions {
      display: flex;
      gap: 6px;
      flex-wrap: wrap;
    }

    .legal {
      width: 100%;
      font-size: 12px;
      opacity: .8;
      display: flex;
      gap: 8px;
      flex-wrap: wrap;
      justify-content: flex-end;
